public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (!(genericType instanceof ParameterizedType)) {
        return null;
    }
    ParameterizedType pt = (ParameterizedType) genericType;
    Type[] argTypes = pt.getActualTypeArguments();
    Class<?>[] result = new Class<?>[argTypes.length];
    for (int i = 0; i < argTypes.length; i++) {
        Class<?> c = getClassForType(argTypes[i], targetType, new java.util.HashMap<>());
        if (c == null) {
            return null;
        }
        result[i] = c;
    }
    return result;
}

private static Class<?> getClassForType(Type t, Class<?> targetType, java.util.Map<TypeVariable<?>, Type> visited) {
    if (t instanceof Class<?>) {
        return (Class<?>) t;
    }
    if (t instanceof ParameterizedType) {
        return (Class<?>) ((ParameterizedType) t).getRawType();
    }
    if (t instanceof TypeVariable<?>) {
        // Resolve type variable using target type hierarchy
        TypeVariable<?> tv = (TypeVariable<?>) t;
        if (visited.containsKey(tv)) {
            return null; // prevent infinite recursion
        }
        java.util.Map<TypeVariable<?>, Type> mapping = getTypeMapping(targetType);
        Type mapped = mapping.get(tv);
        if (mapped == null) {
            return null;
        }
        visited.put(tv, mapped);
        return getClassForType(mapped, targetType, visited);
    }
    if (t instanceof WildcardType) {
        Type[] uppers = ((WildcardType) t).getUpperBounds();
        if (uppers.length == 1) {
            return getClassForType(uppers[0], targetType, visited);
        }
        return null;
    }
    return null;
}

