static long compressTimeBucket(long timeBucket,int dayStep){
    if(dayStep <= 0){
        throw new IllegalArgumentException("dayStep must be positive");
    }
    int year  = (int)(timeBucket / 10000);
    int month = (int)((timeBucket / 100) % 100);
    int day   = (int)(timeBucket % 100);
    java.time.LocalDate date;
    try{
        date = java.time.LocalDate.of(year, month, day);
    }catch(java.time.DateTimeException e){
        throw new IllegalArgumentException("Invalid date: " + timeBucket, e);
    }
    int offset = (date.getDayOfMonth() - 1) % dayStep;
    java.time.LocalDate bucketStart = date.minusDays(offset);
    return bucketStart.getYear() * 10000L + bucketStart.getMonthValue() * 100L + bucketStart.getDayOfMonth();
}

public static int computeUTF8Size(final CharSequence str,final int index,final int len){
    int size = 0;
    int i = index;
    final int end = index + len;
    while (i < end) {
        int cp = str.codePointAt(i);
        if (cp <= 0x7F) {
            size += 1;
        } else if (cp <= 0x7FF) {
            size += 2;
        } else if (cp <= 0xFFFF) {
            size += 3;
        } else {
            size += 4;
        }
        i += Character.charCount(cp);
    }
    return size;
}

