public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    if (str == null || str.length() == 0) {
        return lb;
    }
    // Convert to UTF‑8 byte array
    byte[] bytes = str.toString().getBytes(StandardCharsets.UTF_8);
    int offset = 0;
    int remaining = bytes.length;
    // Write bytes to the provided LinkedBuffer in a loop until finished
    while (remaining > 0) {
        // Assuming LinkedBuffer has a write method that returns the number of bytes written
        int written = lb.write(bytes, offset, remaining);
        offset += written;
        remaining -= written;
    }
    return lb;
}

