        throw new IndexOutOfBoundsException("Index out of bounds: i=" + i + ", j=" + j + ", array length=" + arr.length);
    }
    if (i != j) {
        V temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
    }
}

