public void readFrom(final InputStream in) throws IOException {
    // Read the entire stream into a temporary buffer first
    ByteArrayOutputStream tmpOut = new ByteArrayOutputStream();
    byte[] chunk = new byte[4096];
    int read;
    while ((read = in.read(chunk)) != -1) {
        tmpOut.write(chunk, 0, read);
    }
    byte[] data = tmpOut.toByteArray();

    // Ensure the internal buffer can hold the data
    if (buf == null || buf.length < data.length) {
        buf = new byte[data.length];
    }

    // Copy data into the internal buffer
    System.arraycopy(data, 0, buf, 0, data.length);

    // Update length and reset read pointer
    length = data.length;  // assuming a field that tracks current size
    pos = 0;                // reset read pointer to the start
}

