@Override
protected Object convertToType(final Class<?> type, final Object value) throws Exception {
    // Fail fast for unsupported target types
    if (!Character.class.isAssignableFrom(type)) {
        throw new IllegalArgumentException(
            "Target type is not java.lang.Character: " + type.getName());
    }

    // Null values stay null
    if (value == null) {
        return null;
    }

    // Direct Character or primitive char (boxed)
    if (value instanceof Character) {
        return value;
    }

    // String: accept only single‑character strings
    if (value instanceof String) {
        String str = (String) value;
        if (str.length() != 1) {
            throw new Exception(
                "Cannot convert String to Character: String length must be 1, was " + str.length()
            );
        }
        return str.charAt(0);
    }

    // Number: cast to char using the integer value
    if (value instanceof Number) {
        return (char) ((Number) value).intValue();
    }

    // Boolean: represent as 't' / 'f'
    if (value instanceof Boolean) {
        return (char) (((Boolean) value) ? 1 : 0);
    }

    // Fallback: attempt string conversion
    String str = value.toString();
    if (str.length() == 1) {
        return str.charAt(0);
    }

    // If none of the above, throw an exception
    throw new Exception(
        "Conversion failed for value: " + value + " (type " + value.getClass().getName() + ")"
    );
}

public static boolean containsAnyIgnoreCase(String str, List<String> searchStrArray) {
    if (str == null || searchStrArray == null || searchStrArray.isEmpty()) {
        return false;
