    char[] sourceChars = str.toCharArray();
    for (String search : searchStrArray) {
        if (search == null) {
            continue;
        }
        char[] searchChars = search.toCharArray();
        for (char sc : searchChars) {
            char scLower = Character.toLowerCase(sc);
            for (char c : sourceChars) {
                if (Character.toLowerCase(c) == scLower) {
                    return true;
                }
            }
        }
    }
    return false;
}

public static int nextPrime(int desiredCapacity){
    if (desiredCapacity <= 2) return 2;
    if (desiredCapacity <= 3) return 3;
    int candidate = desiredCapacity;
    if (candidate % 2 == 0) candidate++;   // make it odd
    while (true) {
        int limit = (int)Math.sqrt(candidate);
        boolean isPrime = true;
        for (int i = 3; i <= limit; i += 2) {
            if (candidate % i == 0) {
                isPrime = false;
                break;
            }
        }
        if (isPrime) return candidate;
        candidate += 2;   // check next odd number
    }
}

