protected int removeUnusedNodes() {
    int removedCount = 0;
    // Assume the roots of the tree are stored in a List<Category> named "roots"
    Iterator<Category> rootIt = roots.iterator();
    while (rootIt.hasNext()) {
        Category root = rootIt.next();
        if (root.isInactive()) {
            removedCount += removeSubtree(root);
            rootIt.remove(); // remove the root from the list
        } else {
            removedCount += pruneInactiveChildren(root);
        }
    }
    return removedCount;
}

private int removeSubtree(Category node) {
    int count = 1; // count the node itself
    List<Category> children = node.getChildren();
    if (children != null) {
        for (Category child : children) {
            count += removeSubtree(child);
        }
        children.clear(); // detach all children
    }
    return count;
}

private int pruneInactiveChildren(Category parent) {
    int count = 0;
    Iterator<Category> childIt = parent.getChildren().iterator();
    while (childIt.hasNext()) {
        Category child = childIt.next();
        if (child.isInactive()) {
            count += removeSubtree(child);
            childIt.remove(); // remove the inactive child from the list
        } else {
            count += pruneInactiveChildren(child);
        }
    }
    return count;
}

