private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    OuterFaceCirculator circ = new OuterFaceCirculator(start, dir);
    Node current = circ.getNode(); // current node in the circulator
    while (true) {
        if (predicate.test(current)) {
            return circ;
        }
        if (current == stop) {
            return circ;
        }
        circ.next(); // advance to the next node of the outer face
        current = circ.getNode();
        if (current == start) { // break in case of full cycle without match
            return circ;
        }
    }
}

