        ConstantPoolItem item = constantPool.get(i);
        if (item instanceof CONSTANT_NameAndType_info) {
            CONSTANT_NameAndType_info nt = (CONSTANT_NameAndType_info) item;
            if (nt.getName().equals(name) && nt.getDescriptor().equals(descriptor)) {
