}

private String unescapeId(String input) {
    if (input == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder();
    char[] chars = input.toCharArray();
    for (int i = 0; i < chars.length; i++) {
        char c = chars[i];
        if (c == '\\' && i + 1 < chars.length) {
            // Handle escape sequence
            i++;
            char esc = chars[i];
            switch (esc) {
                case 'n':
                    sb.append('\n');
                    break;
                case 'r':
                    sb.append('\r');
                    break;
                case 't':
                    sb.append('\t');
                    break;
                case 'b':
                    sb.append('\b');
                    break;
                case 'f':
                    sb.append('\f');
                    break;
                case '0':
                    sb.append('\0');
                    break;
                case '\\':
                    sb.append('\\');
                    break;
                case '\"':
                    sb.append('\"');
                    break;
                case '\'':
                    sb.append('\'');
                    break;
                case 'x':
                    // Hex escape \xhh
                    if (i + 2 < chars.length) {
                        String hex = new String(chars, i + 1, 2);
                        try {
                            int val = Integer.parseInt(hex, 16);
                            sb.append((char) val);
                            i += 2;
                        } catch (NumberFormatException e) {
                            sb.append('x');
                        }
                    } else {
                        sb.append('x');
                    }
                    break;
                case 'u':
                    // Unicode escape \uhhhh
                    if (i + 4 < chars.length) {
                        String hex = new String(chars, i + 1, 4);
                        try {
                            int val = Integer.parseInt(hex, 16);
                            sb.append((char) val);
                            i += 4;
                        } catch (NumberFormatException e) {
                            sb.append('u');
                        }
                    } else {
                        sb.append('u');
                    }
                    break;
                default:
                    sb.append(esc);
                    break;
            }
        } else {
            sb.append(c);
        }
    }
    return sb.toString();
}

