public ByteVector putInt(final int intValue){
    // Ensure the internal array can hold 4 more bytes
    if (count + 4 > data.length) {
        // Resize: at least double the size or enough for the 4 new bytes
        int newCapacity = Math.max((count + 4), data.length * 2);
        byte[] newData = new byte[newCapacity];
        System.arraycopy(data, 0, newData, 0, count);
        data = newData;
    }
    // Store the int in big‑endian order
    data[count++] = (byte)((intValue >>> 24) & 0xFF);
    data[count++] = (byte)((intValue >>> 16) & 0xFF);
    data[count++] = (byte)((intValue >>> 8)  & 0xFF);
    data[count++] = (byte)(intValue & 0xFF);
    return this;
}

public static boolean arrayequals(byte[] a, byte[] b, int count) {
    if (a == b) return true;
    if (a == null || b == null) return false;
    if (count <= 0) return true;
    if (count > a.length || count > b.length) return false;
    for (int i = 0; i < count; i++) {
        if (a[i] != b[i]) return false;
    }
    return true;
}

public void abbreviate(final int nameStart, final StringBuffer buf){
    if (buf == null || nameStart < 0) {
        return;
    }
    String s = this.name;
    if (s == null || nameStart >= s.length()) {
        return;
    }
    boolean newWord = true;
    for (int i = nameStart; i < s.length(); i++) {
        char c = s.charAt(i);
        if (Character.isWhitespace(c) || c == '-') {
            newWord = true;
        } else if (newWord) {
            buf.append(Character.toUpperCase(c)).append('.');
            newWord = false;
        }
    }
}

public static Type resolveBound(TypeVariable<?> typeVariable) {
    if (typeVariable == null) {
        return Unknown.class;
    }

    Type[] bounds = typeVariable.getBounds();
    if (bounds == null || bounds.length == 0) {
        return Unknown.class;
    }

    for (Type bound : bounds) {
        if (bound instanceof Class<?>) {
            return bound;
        }
        if (bound instanceof ParameterizedType) {
            Type raw = ((ParameterizedType) bound).getRawType();
            if (raw instanceof Class<?>) {
                return raw;
            }
        }
        // Skip other kinds of bounds (WildcardType, GenericArrayType, etc.)
    }

    return Unknown.class;
}

private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    if (graph == null || vertices == null) {
        return false;
    }
    int n = vertices.size();
    if (n <= 1) {
        return true;
    }
    List<V> vertexList = new ArrayList<>(vertices);
    for (int i = 0; i < n - 1; i++) {
        V vi = vertexList.get(i);
        for (int j = i + 1; j < n; j++) {
            V vj = vertexList.get(j);
            if (graph.getEdge(vi, vj) == null) {
                return false;
            }
        }
    }
    return true;
}

private List<Integer> computeLowerBounds(List<K> keys){
    List<Integer> bounds = new java.util.ArrayList<>(keys.size());
    for (K key : keys) {
        int idx = java.util.Collections.binarySearch(keys, key);
        int lower;
        if (idx >= 0) {
            lower = idx;
        } else {
            int insertionPoint = -idx - 1;
            lower = insertionPoint - 1;
        }
        bounds.add(lower);
    }
    return bounds;
}

