static String[] toNoNullStringArray(Object[] array){
    if (array == null) {
        return null;
    }
    boolean hasNull = false;
    for (Object o : array) {
        if (o == null) {
            hasNull = true;
            break;
        }
    }
    if (!hasNull) {
        return (String[]) array;
    }
    String[] temp = new String[array.length];
    int idx = 0;
    for (Object o : array) {
        if (o != null) {
            temp[idx++] = (String) o;
        }
    }
    return idx == array.length ? temp
           : java.util.Arrays.copyOf(temp, idx);
}

public static int indexOfExtension(String filename){
