public static boolean substringMatch(CharSequence str,int index,CharSequence substring){
    if (str == null || substring == null) {
        return false;
    }
    int strLen = str.length();
    int subLen = substring.length();
    if (index < 0 || index > strLen) {
        return false;
    }
    if (subLen == 0) {
        return index <= strLen;
    }
    if (index + subLen > strLen) {
        return false;
    }
    for (int i = 0; i < subLen; i++) {
        if (str.charAt(index + i) != substring.charAt(i)) {
            return false;
        }
    }
    return true;
}

protected void append(LoggingEvent event) {
    // Convert the event to a string
    String message = (event != null) ? event.getRenderedMessage() : "";
    if (layout != null) {
        message = layout.format(event);
    }
    // Write to each connected client
    for (Iterator<PrintWriter> it = clients.iterator(); it.hasNext(); ) {
        PrintWriter writer = it.next();
        try {
            writer.println(message);
            writer.flush();
        } catch (IOException e) {
            // If the client connection fails, remove it from the list
            it.remove();
        }
    }
}

private void checkIfPackedField() throws IOException {
    // Determine the wire type and field number from the current tag.
    int tag = this.currentTag;
    int wireType = tag & 0x7;        // last 3 bits
    int fieldNumber = tag >>> 3;     // remaining bits

    // Packed repeated fields use wire type LENGTH_DELIMITED (value 2).
    // If the current tag indicates a length-delimited field and the
    // schema tells us that this field is a repeated primitive type,
    // set the internal flag indicating that packed fields are being
    // read.  The actual schema lookup and field descriptor is
    // provided by the subclass or surrounding context.
    if (wireType == com.google.protobuf.WireFormat.WIRETYPE_LENGTH_DELIMITED) {
        FieldDescriptor<?> descriptor = schema.getDescriptor(fieldNumber);
        if (descriptor != null
                && descriptor.isRepeated()
                && descriptor.isPrimitive()
                && descriptor.isPacked()) {
            this.isPacked = true;
            this.packedFieldNumber = fieldNumber;
            this.packedLength = descriptor.getLength();
        } else {
            this.isPacked = false;
        }
    } else {
        this.isPacked = false;
    }
}

public int readTag() throws IOException {
    // Return 0 if we have reached the end of the input.
    if (this.isAtEnd()) {
        return 0;
    }
    // Read a varint-encoded tag from the input.
    int tag = 0;
    int shift = 0;
    while (true) {
        if (shift >= 32) {
            throw new InvalidProtocolBufferException("Protocol message had too many bytes for a tag.");
        }
        byte b = readRawByte();
        tag |= (b & 0x7F) << shift;
        if ((b & 0x80) == 0) {
            break;  // The most significant bit indicates the end of the varint.
        }
        shift += 7;
    }
    return tag;
}

final ByteVector put11(final int byteValue1,final int byteValue2){
    if (this.len + 2 > this.code.length) {
        int newLen = this.len + 2;
        byte[] newCode = new byte[Math.max(newLen, this.code.length << 1)];
        System.arraycopy(this.code, 0, newCode, 0, this.len);
        this.code = newCode;
    }
    this.code[this.len++] = (byte) byteValue1;
    this.code[this.len++] = (byte) byteValue2;
    return this;
}

private String buildContentRange() {
    // Assuming fields named start, end, and totalLength exist in the class.
    long start = this.start;
    long end = this.end;
    long total = this.totalLength;
    if (start < 0 || end < 0) {
        return null;
    }
    if (total >= 0) {
        return String.format("bytes %d-%d/%d", start, end, total);
    } else {
        return String.format("bytes %d-%d/*", start, end);
    }
}

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    // Load all thread snapshots from the file (assumes the file contains a serialized List<ThreadSnapshot>)
    List<ThreadSnapshot> allSnapshots;
    try (ObjectInputStream ois = new ObjectInputStream(new FileInputStream(file))) {
        Object obj = ois.readObject();
        if (obj instanceof List<?>) {
            allSnapshots = (List<ThreadSnapshot>) obj;
        } else {
            // If the file does not contain a List, return an empty list
            allSnapshots = Collections.emptyList();
        }
    } catch (ClassNotFoundException e) {
        throw new IOException("Failed to deserialize thread snapshots from file: " + e.getMessage(), e);
    }

    // Filter snapshots that fall within any of the specified time ranges
    List<ThreadSnapshot> result = new ArrayList<>();
    for (ThreadSnapshot snapshot : allSnapshots) {
        if (snapshot == null) {
            continue;
        }
        long ts = snapshot.getTimestamp(); // assume ThreadSnapshot provides a getTimestamp() method
        for (ProfileAnalyzeTimeRange range : timeRanges) {
            if (ts >= range.getStartTime() && ts <= range.getEndTime()) {
                result.add(snapshot);
                break; // No need to check other ranges
            }
        }
    }
    return result;
}
